searched_case.sql:
CREATE PROCEDURE p (IN v INTEGER)
LANGUAGE SQL
BEGIN
  CASE WHEN v = 1 THEN UPDATE t SET c = 1; END CASE;
END;

searched_case_else.sql:
CREATE PROCEDURE p (IN v INTEGER)
LANGUAGE SQL
BEGIN
  CASE WHEN v = 1 THEN UPDATE t SET c = 1; WHEN v = 2 THEN UPDATE t SET c = 2; ELSE UPDATE t SET c = 3; END CASE;
END;

